import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Collections;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Jaynil
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ERockPaperScissors solver = new ERockPaperScissors();
        solver.solve(1, in, out);
        out.close();
    }

    static class ERockPaperScissors {
        int min;

        public void check(ArrayList<int[]> aa, int a[], int b[]) {
            for (int i = 0; i < aa.size(); i++) {
                int m = Math.min(a[aa.get(i)[0]], b[aa.get(i)[1]]);
                b[aa.get(i)[1]] -= m;
                a[aa.get(i)[0]] -= m;
            }
            int curr = 0;
            for (int i = 0; i < 3; i++) curr += a[i];
            min = Math.min(min, curr);
        }

        public void per(ArrayList<int[]> aa, int index, int a[], int b[]) {
            check(aa, a.clone(), b.clone());
            for (int i = index; i < aa.size(); i++) {
                Collections.swap(aa, i, index);
                per(aa, index + 1, a, b);
                Collections.swap(aa, i, index);
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int a[] = new int[3];
            int b[] = new int[3];
            min = Integer.MAX_VALUE;
            int max = 0;
            for (int i = 0; i < 3; i++) {
                a[i] = in.nextInt();
            }
            for (int i = 0; i < 3; i++) {
                b[i] = in.nextInt();
            }
            max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            ArrayList<int[]> aa = new ArrayList<>();
            aa.add(new int[]{0, 0});
            aa.add(new int[]{1, 1});
            aa.add(new int[]{2, 2});
            aa.add(new int[]{0, 2});
            aa.add(new int[]{1, 0});
            aa.add(new int[]{2, 1});
            per(aa, 0, a, b);
            out.println(min + " " + max);
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}


